"""Every rounding rule of meterbill lives here (see docs/rounding.md).

All decimal arithmetic in this module is exact integer arithmetic, so the
result never depends on the decimal context, which is never touched.
"""

from __future__ import annotations

from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or not step > 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _fraction(d: Decimal) -> Fraction:
    sign, digits, exp = d.as_tuple()
    n = int("".join(map(str, digits)) or "0")
    if sign:
        n = -n
    return Fraction(n) * (Fraction(10) ** exp)


def _units(value: Decimal, step: Decimal, method: str) -> int:
    """The signed number of steps nearest to `value`."""
    q = _fraction(value) / _fraction(step)
    neg = q < 0
    q = abs(q)
    n = q.numerator // q.denominator
    rest = q - n
    if method != DOWN:
        half = Fraction(1, 2)
        if rest > half or (rest == half and (method == HALF_UP or n % 2 == 1)):
            n += 1
    return -n if neg else n


def _build(units: int, step: Decimal, negative: bool) -> Decimal:
    """`units` steps as a Decimal with the exponent of `step`."""
    _, sdigits, exp = step.as_tuple()
    coef = int("".join(map(str, sdigits)))
    n = abs(units) * coef
    digits = tuple(int(c) for c in str(n))
    return Decimal((1 if (units < 0 or (units == 0 and negative)) else 0, digits, exp))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    return _build(_units(value, step, method), step, value.is_signed())


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    amounts = list(amounts)
    for a in amounts:
        _check(a, step, DOWN)
    _check(Decimal(0), step, DOWN)
    units = [_units(a, step, DOWN) for a in amounts]
    total = sum((_fraction(a) for a in amounts), Fraction(0))
    whole = _units(_total_decimal(total), step, HALF_UP)
    rest = whole - sum(units)
    parts = [_build(u, step, a.is_signed()) for u, a in zip(units, amounts)]
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _build(units[i] + rest, step, False)
            break
    return parts


def _total_decimal(f: Fraction) -> Decimal:
    # Only used to feed _units: keep the exact fraction by way of a scaled Decimal.
    # Denominators are powers of ten here (sums of decimals), so this is exact.
    den = f.denominator
    exp = 0
    while den % 10 == 0:
        den //= 10
        exp += 1
    while den % 2 == 0:
        den //= 2
        exp += 1
    while den % 5 == 0:
        den //= 5
        exp += 1
    scale = Fraction(10) ** exp
    n = f * scale
    assert n.denominator == 1
    s = n.numerator
    return Decimal((1 if s < 0 else 0, tuple(int(c) for c in str(abs(s))), -exp))


def legacy_cents(value: float, places: int = 2) -> float:
    import math

    if not isinstance(places, int) or isinstance(places, bool) or not 0 <= places <= 6:
        raise ValueError("places must be an integer from 0 to 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(value, Decimal):
        if method not in _METHODS:
            raise ValueError(f"unknown rounding method {method!r}")
        if not value.is_finite():
            return format(value, "f")
        step = _build(1, Decimal(1), False).scaleb(-places) if places else Decimal(1)
        r = round_amount(value, step, method)
        return _plain(r)
    if method != HALF_EVEN:
        raise ValueError("a float is only written half to even")
    return format(value, f".{places}f")


def _plain(d: Decimal) -> str:
    sign, digits, exp = d.as_tuple()
    s = "".join(map(str, digits))
    if exp >= 0:
        s += "0" * exp
    else:
        s = s.rjust(-exp + 1, "0")
        s = s[:exp] + "." + s[exp:]
    return ("-" if sign else "") + s
